package api;
import com.microsoft.playwright.APIRequestContext;
import com.microsoft.playwright.APIResponse;
import framework.CommonMethods;
public final class UserService {
  private final APIRequestContext request;
  private APIResponse usersResponse;
  public UserService(APIRequestContext request) { this.request = request; }
  public APIResponse getUsers() { return request.get(String.valueOf(CommonMethods.testData().getOrDefault("apiBaseUrl", "https://jsonplaceholder.typicode.com")) + "/users"); }
  public void requestUsers() { usersResponse = getUsers(); }
  public void verifyUsersResponse() { if (usersResponse == null || usersResponse.status() != ((Number) CommonMethods.testData().get("apiExpectedStatus")).intValue() || usersResponse.text().isBlank()) throw new AssertionError("Users response was not successful"); }
  public void verifyUsersAvailable() { requestUsers(); verifyUsersResponse(); }
}
